from itertools import permutations

def is_costas(perm):
    """Check if a permutation is a Costas array."""
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

# Try to find a Costas array of order 12 with x[3]=8, x[8]=2
# This is a search problem - let's use backtracking

def solve_costas(n, fixed):
    """Find a Costas array of order n with fixed assignments."""
    # fixed is a dict of {column: row}

    # Build the permutation with fixed values
    perm = [None] * n
    for col, row in fixed.items():
        perm[col] = row

    used_rows = set(fixed.values())

    def backtrack(col):
        if col == n:
            # Check if it's a valid Costas array
            return is_costas(perm)

        if perm[col] is not None:
            return backtrack(col + 1)

        for row in range(n):
            if row in used_rows:
                continue

            perm[col] = row
            used_rows.add(row)

            # Early pruning: check partial Costas property
            valid = True
            for prev_col in range(col):
                if perm[prev_col] is not None:
                    dr = perm[col] - perm[prev_col]
                    dc = col - prev_col
                    # We need to check this vector hasn't appeared before
                    # But we need to check all pairs, not just with current col
                    # This is expensive, so let's just do full check at the end for now

            if backtrack(col + 1):
                return True

            perm[col] = None
            used_rows.remove(row)

        return False

    if backtrack(0):
        return perm
    return None

